<?php
if (PHP_SAPI !== 'cli') { http_response_code(403); echo "CLI only\n"; exit(1); }
$root=dirname(__DIR__,2);require_once $root.'/config.php';
require_once $root.'/base/SmtpMailer.class.php';
$db=new mysqli($conf['db_server'],$conf['db_username'],$conf['db_password'],$conf['db_name']);if($db->connect_error){fwrite(STDERR,"DB connect error\n");exit(1);}$db->set_charset('utf8mb4');
$db->query("CREATE TABLE IF NOT EXISTS game_email_delivery_log (delivery_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,email_id BIGINT UNSIGNED NOT NULL,transport VARCHAR(32) NOT NULL,status VARCHAR(16) NOT NULL,response_text VARCHAR(500) NOT NULL DEFAULT '',attempted_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_game_email_delivery(email_id,attempted_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$transport=getenv('GAME_MAIL_TRANSPORT')?:'log';$mailer=new SmtpMailer();$rows=$db->query("SELECT email_id,from_address,to_address,subject,body FROM game_email_messages WHERE delivery_status='queued' ORDER BY email_id ASC LIMIT 100");$count=0;while($rows&&($row=$rows->fetch_assoc())){$id=(int)$row['email_id'];$status='sent';$response='queued for in-game delivery';if($transport==='smtp'){$result=$mailer->send($row['to_address'],$row['subject'],$row['body']);$status=$result['ok']?'sent':'failed';$response=$result['response'];}elseif($transport==='log'){$response='log-only transport; external SMTP not attempted';}else{$status='failed';$response='unsupported mail transport';}$db->begin_transaction();$stmt=$db->prepare("UPDATE game_email_messages SET delivery_status=?,sent_at=IF(?='sent',NOW(),sent_at) WHERE email_id=? AND delivery_status='queued'");$stmt->bind_param('ssi',$status,$status,$id);$stmt->execute();$log=$db->prepare('INSERT INTO game_email_delivery_log(email_id,transport,status,response_text) VALUES(?,?,?,?)');$log->bind_param('isss',$id,$transport,$status,$response);$log->execute();$db->commit();$count++;}echo "email_tick: processed $count queued messages using $transport transport\n";$db->close();
?>
